import {createDocumentSession} from './document-session.js';
import {DOCUMENT_TYPES,DOCUMENT_FIELDS,FIELD_BY_ID,documentValue} from './document-schema.js';
import {documentConflicts,applyDocumentCase,compareDocumentReference} from './document-case.js';
import {calcEscape as esc} from './calculator-view.js';
const labels={queued:'Oczekuje',reading:'Odczyt PDF',ocr:'Lokalny odczyt skanu',ready:'Odczyt zakończony',error:'Wymaga uwagi',cancelled:'Przerwano'};
const paths={family:'Macierzyński / rodzicielski / ojcowski',sickness:'Chorobowe',rehab:'Rehabilitacyjne',care:'Opiekuńczy',prebirth:'Utrata pracy przed porodem'};
const help=`<details class="doc-legend"><summary>Wyjaśnienia — dokumenty i odczyt</summary><dl><dt>Odczytano z dokumentu</dt><dd>Informacja pochodzi z lokalnego odczytu tekstu, pola PDF lub OCR. Nie stanowi urzędowego potwierdzenia.</dd><dt>Ubezpieczenie chorobowe</dt><dd>Może być obowiązkowe, dobrowolne, nie istnieć lub pozostawać nieustalone. Brak wzmianki nie oznacza braku ubezpieczenia.</dd><dt>Płatnik składek</dt><dd>To np. pracodawca; jego dane nie są danymi rodzica. Nie zawsze płatnik składek wypłaca zasiłek.</dd><dt>Podstawa wymiaru</dt><dd>Podstawa zasiłku różni się od wynagrodzenia brutto, podstawy składek i przelewu netto. Kwoty miesięczne trzeba przypisać do właściwych miesięcy i tytułów.</dd><dt>Okres ubezpieczenia / powstanie prawa</dt><dd>To różne daty. Sama data wystawienia zaświadczenia nie rozpoczyna ubezpieczenia ani świadczenia.</dd><dt>Wykorzystane urlopy</dt><dd>Dotyczą konkretnego rodzica i dziecka. W kalkulatorze sprawdź również rejestr wcześniejszych okresów i faktycznych wypłat.</dd><dt>Dokumenty medyczne i odmowa</dt><dd>Odczyt nie diagnozuje choroby ani nie ustala niepełnosprawności. ZUS może wymagać orzeczenia lub oceny indywidualnej. Przyczynę braku prawa lub brakujące dane wyjaśnia wspólny kalkulator.</dd><dt>Wersje formularzy</dt><dd>Rozpoznanie symbolu nie potwierdza wydania wzoru. Starsze formularze można odczytać do spraw historycznych; do nowego wniosku sprawdź aktualny wzór w ZUS.</dd></dl></details>`;
export function createDocumentWorkspace({getInput,onApply,onManual,notify,getResult=()=>null}){
 const dialog=document.createElement('dialog');dialog.className='document-dialog';dialog.setAttribute('aria-label','Sprawdź sprawę na podstawie dokumentów');document.body.append(dialog);let previewJob=Promise.resolve();let stage='start',preview=null,previewSerial=0,focus='family',familyType='birth',primaryParent=0,pendingSource=null;
 const session=createDocumentSession(()=>{if(dialog.open)refresh();});window.addEventListener('pagehide',()=>session.dispose(),{once:true});
 function error(e){const node=dialog.querySelector('#doc-error');if(node){node.hidden=false;node.textContent=e.message||'Sprawdź wskazane dane.';}else notify(e.message);}
 function refresh(){// Preserve edits and the preview while OCR reports progress.
  if(dialog.querySelector('#doc-list')){drawList();drawFields();return;}draw();
 }
 function draw(){const c=session.current();dialog.innerHTML=`<header class="doc-header"><div><span class="eyebrow">Zintegrowany Kalkulator</span><h1>Sprawdź sprawę na podstawie dokumentów</h1></div><button class="icon-button" id="doc-close" aria-label="Zamknij">×</button></header><div class="doc-content"><p class="doc-privacy">PDF-y i ich odczyt pozostają w pamięci tej karty. Nie są wysyłane do AI ani zapisywane na serwerze. Po zamknięciu karty pliki znikają. Do zapisania scenariusza potrzebne będzie osobne potwierdzenie danych strukturalnych.</p><p id="doc-error" class="calc-error" role="alert" hidden></p>${stage==='start'?`<div class="doc-choices"><button id="doc-upload-choice"><strong>A. Wgraj dokumenty PDF</strong><span>Jeden wniosek lub cały zestaw zaświadczeń. Odczyt lokalny, również ze skanów.</span></button><button id="doc-example-choice"><strong>B. Wybierz przykładową sprawę</strong><span>Własne, fikcyjne dokumenty — bez publikowania materiałów konkursowych.</span></button><button id="doc-manual-choice"><strong>C. Wpisz dane ręcznie</strong><span>Ten sam kalkulator, bez dodawania dokumentów.</span></button></div>${c.documents.length?'<button class="secondary" id="doc-resume">Wróć do dokumentów tej sesji</button>':''}`:`<div class="doc-toolbar"><label>Sprawa<select id="doc-case">${session.cases.map(c=>`<option value="${c.id}" ${c===session.current()?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><button class="secondary" id="doc-new-case">Nowa sprawa</button><button class="secondary" id="doc-clear">Usuń wszystkie dokumenty tej sprawy</button><button class="text-button" id="doc-options">Sposób uzupełnienia</button></div><label id="doc-drop" class="doc-drop"><strong>Dodaj PDF-y do tej sprawy</strong><span>Wybierz pliki lub przeciągnij je tutaj. Do 40 plików, 32 MB na plik, 400 stron w zestawie.</span><input id="doc-files" type="file" accept="application/pdf,.pdf" multiple></label><div id="doc-list" aria-live="polite"></div><div class="doc-review-layout"><section class="doc-review"><h2>Sprawdź odczytane dane</h2><p>Nie łączymy osób na podstawie samego PESEL. Przypisz rodzica, tytuł ubezpieczenia i dziecko. Przy różnych osobach lub świadczeniach przenieś dokument do oddzielnej sprawy.</p><div class="doc-settings"><label>Co sprawdzamy?<select id="doc-focus">${Object.entries(paths).map(([id,label])=>`<option value="${id}" ${focus===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Sytuacja rodzinna<select id="doc-family">${[['birth','Urodzenie'],['adoption','Adopcja'],['foster','Piecza niezawodowa'],['professional','Piecza zawodowa'],['unknown','Do ustalenia']].map(([id,label])=>`<option value="${id}" ${familyType===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Osoba wnioskująca<select id="doc-primary"><option value="0" ${primaryParent===0?'selected':''}>Matka / opiekun 1</option><option value="1" ${primaryParent===1?'selected':''}>Ojciec / opiekun 2</option></select></label></div><p id="doc-path-suggestions" class="doc-ref-summary"></p><div id="doc-fields"></div><details class="doc-candidates"><summary>Odczytane daty i kwoty wymagające przypisania</summary><p>Nie przypisujemy wartości na podstawie samego wyglądu. Sprawdź kolumnę, osobę i opis, a następnie wybierz właściwe pole.</p><div id="doc-candidates"></div></details><details class="doc-manual"><summary>Dodaj brakujące pole ręcznie</summary><label>Pole<select id="doc-manual-field">${DOCUMENT_FIELDS.filter(f=>!['reference','payer','information'].includes(f.scope)&&!f.id.startsWith('identity.')).map(f=>`<option value="${f.id}">${esc(f.label)}</option>`).join('')}<option value="wage.gross">Wynagrodzenie brutto za miesiąc</option><option value="wage.deducted">Potrącone składki za miesiąc</option><option value="wage.worked">Dni pracy za miesiąc</option><option value="wage.scheduled">Dni wymagane za miesiąc</option></select></label><label>Wartość<input id="doc-manual-value"></label><label>Miesiąc, jeżeli dotyczy<input id="doc-manual-month" type="month"></label><button class="secondary" id="doc-add-field">Dodaj do kontroli</button></details><label class="doc-confirm"><input type="checkbox" id="doc-confirm"> Sprawdziłem wybrane wartości, ich właścicieli, miesiące i okresy. Potwierdzam dane do obliczenia.</label><label class="doc-confirm"><input type="checkbox" id="doc-replace"> Zgadzam się zastąpić odpowiednie pola bieżącego formularza. Zapisane scenariusze i profil pozostaną zachowane.</label><button class="primary" id="doc-apply">Użyj potwierdzonych danych w kalkulatorze</button><p>Niepotwierdzone informacje nie są podstawą wyliczenia. Pozostałe warunki, historię urlopów i brakujące pola sprawdzisz w kolejnych krokach kalkulatora.</p>${help}<details id="doc-reference"><summary>Tryb sprawdzania — wynik referencyjny</summary><p>Decyzja i wykaz wypłat nie są danymi wejściowymi. Porównanie jest dostępne dopiero po własnym obliczeniu i tylko w tym trybie.</p><div id="doc-reference-fields"></div></details></section><aside class="doc-preview"><h2>Oryginalny dokument</h2><div id="doc-preview-controls">Kliknij „Zobacz źródło” przy wartości albo „Podgląd” przy dokumencie.</div><div class="doc-canvas-wrap"><canvas id="doc-canvas" hidden></canvas></div><p id="doc-preview-message"></p></aside></div>`}</div>`;
  dialog.querySelector('#doc-close').onclick=()=>dialog.close();
  dialog.querySelector('#doc-upload-choice')?.addEventListener('click',()=>{stage='review';draw();dialog.querySelector('#doc-files').click();});dialog.querySelector('#doc-example-choice')?.addEventListener('click',examples);dialog.querySelector('#doc-manual-choice')?.addEventListener('click',()=>{dialog.close();onManual();});dialog.querySelector('#doc-resume')?.addEventListener('click',()=>{stage='review';draw();});if(stage==='start')return;
  dialog.querySelector('#doc-files').onchange=e=>add(e.target.files);const drop=dialog.querySelector('#doc-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragging');};drop.ondragleave=()=>drop.classList.remove('dragging');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragging');add(e.dataTransfer.files);};dialog.querySelector('#doc-case').onchange=e=>{session.select(e.target.value);preview=null;draw();};dialog.querySelector('#doc-new-case').onclick=()=>{session.newCase();preview=null;draw();};dialog.querySelector('#doc-clear').onclick=()=>{if(confirm('Usunąć dokumenty i odczytane dane tej sprawy z bieżącej sesji?')){session.clear();preview=null;draw();}};dialog.querySelector('#doc-options').onclick=()=>{stage='start';draw();};for(const [id,handler]of [['doc-focus',v=>focus=v],['doc-family',v=>familyType=v],['doc-primary',v=>primaryParent=Number(v)]])dialog.querySelector('#'+id).onchange=e=>{handler(e.target.value);drawFields();};
  dialog.querySelector('#doc-add-field').onclick=()=>{const id=dialog.querySelector('#doc-manual-field').value,definition=FIELD_BY_ID[id]||{label:id,type:/worked|scheduled/.test(id)?'integer':'money',scope:'person'},value=dialog.querySelector('#doc-manual-value').value,check=documentValue(definition.type,value);if(!check.valid)return error(new Error(check.reason));c.fields.push({id:crypto.randomUUID(),field:id,label:definition.label,value:check.value,valueType:definition.type,scope:definition.scope,documentId:pendingSource?.documentId||null,page:pendingSource?.page||null,bbox:pendingSource?.bbox||null,method:'manual',evidence:pendingSource?.evidence||'Uzupełniono ręcznie',structuralValid:true,needsReview:true,use:false,assignment:'',title:0,child:0,period:dialog.querySelector('#doc-manual-month').value||null});pendingSource=null;drawFields();};
  dialog.querySelector('#doc-apply').onclick=()=>{try{if(c.documents.some(d=>['queued','reading','ocr'].includes(d.status)))throw new Error('Poczekaj na zakończenie odczytu lub przerwij analizę.');if(!dialog.querySelector('#doc-confirm').checked)throw new Error('Sprawdź i potwierdź wybrane pola.');if(!dialog.querySelector('#doc-replace').checked)throw new Error('Potwierdź zastąpienie odpowiednich pól bieżącego formularza.');const fields=c.fields.map(f=>({...f,confirmed:f.use===true}));const input=applyDocumentCase(getInput(),fields,{focus,familyType,primaryParent});c.fields=fields;c.confirmed=fields.filter(f=>f.confirmed);onApply(input,{caseId:c.id});dialog.close();}catch(e){error(e);}};
  dialog.querySelector('#doc-reference').ontoggle=e=>{if(e.target.open)drawReference();};drawList();drawFields();if(preview)showSource(preview.id,preview.page,preview.bbox);
 }
 async function add(files){try{await session.add([...files]);}catch(e){error(e);}}
 function drawList(){const c=session.current(),node=dialog.querySelector('#doc-list');if(!node)return;node.innerHTML=(c.notice?`<p class="calc-notice">${esc(c.notice)}</p>`:'')+c.documents.map(d=>`<article class="doc-file"><div><strong>${esc(d.file.name)}</strong><span>${labels[d.status]} · ${d.pageCount??'—'} stron${['reading','ocr'].includes(d.status)?' · strona '+(d.page||1)+' · '+d.progress+'%':''}</span>${d.error?`<p>${esc(d.error)}</p>`:''}${d.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}<small>${esc(d.pages[0]?.analysis.type.name||'Rozpoznanie po odczycie')} · ${esc(d.pages[0]?.analysis.type.version||'Wersja nieustalona')}</small><details class="doc-list-type"><summary>Rozpoznanie i kompletność stron</summary>${d.pages.map(p=>`<p>Strona ${p.number}: ${esc(p.analysis.type.id)} · ${esc(p.contentKind||p.method)} · ${p.analysis.fields.length} odczytanych pól${p.analysis.tableDetected?' · tabela':''}. ${esc(p.analysis.type.historicalNotice||'')} ${esc(p.analysis.type.version)}.</p>${p.analysis.unmapped.length?`<p>${p.analysis.unmapped.length} pól formularza wymaga ręcznego przypisania.</p>`:''}<a href="${esc(p.analysis.type.source)}" target="_blank" rel="noopener noreferrer">Oficjalne wzory i procedura ZUS ↗</a>`).join('')}</details></div><div class="doc-file-actions"><button class="secondary" data-preview="${d.id}">Podgląd</button><button class="secondary" data-retry="${d.id}">Odczytaj ponownie</button>${d.status==='error'?`<input data-password="${d.id}" type="password" placeholder="Hasło do PDF" autocomplete="off" aria-label="Hasło do dokumentu">`:''}${['queued','reading','ocr'].includes(d.status)?`<button class="secondary" data-cancel="${d.id}">Przerwij</button>`:''}<button class="text-button" data-remove="${d.id}">Usuń</button><label>Dane osoby w dokumencie<select data-doc-owner="${d.id}"><option value="">Przypisz osobę</option><option value="0" ${d.assignment==='0'?'selected':''}>Matka / opiekun 1</option><option value="1" ${d.assignment==='1'?'selected':''}>Ojciec / opiekun 2</option></select></label><label>Rodzaj dokumentu<select data-type="${d.id}"><option value="">Rozpoznaj automatycznie</option>${DOCUMENT_TYPES.map(t=>`<option value="${t.id}" ${d.override===t.id?'selected':''}>${esc(t.id+' — '+t.name)}</option>`).join('')}</select></label>${session.cases.length>1?`<label>Przenieś do sprawy<select data-move="${d.id}"><option value="">Wybierz</option>${session.cases.filter(x=>x!==c).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label>`:''}</div></article>`).join('');
  node.querySelectorAll('[data-doc-owner]').forEach(s=>s.onchange=()=>{const doc=c.documents.find(d=>d.id===s.dataset.docOwner);doc.assignment=s.value;for(const f of c.fields.filter(f=>f.documentId===doc.id&&f.scope==='person'&&!f.confirmed))f.assignment=s.value;drawFields();});node.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>showSource(b.dataset.preview,1));node.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{const password=node.querySelector('[data-password="'+b.dataset.retry+'"]')?.value;session.retry(b.dataset.retry,password);});node.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>session.cancel(b.dataset.cancel));node.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{session.remove(b.dataset.remove);if(preview?.id===b.dataset.remove){preview=null;draw();}});node.querySelectorAll('[data-type]').forEach(b=>b.onchange=()=>{const d=c.documents.find(d=>d.id===b.dataset.type);d.override=b.value;session.retry(d.id);});node.querySelectorAll('[data-move]').forEach(b=>b.onchange=()=>session.move(b.dataset.move,b.value));
 }
 function drawFields(){const node=dialog.querySelector('#doc-fields');if(!node)return;const c=session.current(),suggestions=[...new Set(c.documents.flatMap(d=>d.pages.map(p=>p.analysis.type.procedure)).map(p=>['adoption','foster'].includes(p)?'family':p).filter(p=>paths[p]))];const hint=dialog.querySelector('#doc-path-suggestions');if(hint)hint.textContent=suggestions.length?'Dokumenty wskazują możliwe zakresy: '+suggestions.map(p=>paths[p]).join(', ')+'. Wybierz sprawdzany zakres powyżej.':'';const conflicts=documentConflicts(c.fields,{selectedOnly:false}),conflictIds=new Set(conflicts.flat().map(f=>f.id));node.innerHTML=conflicts.length?'<p class="calc-notice">Znaleźliśmy różne wartości tego samego pola. Poniżej wskazujemy dokumenty i strony. Rozbieżność może zmienić prawo, okres lub kwotę świadczenia — wybierz poprawną wartość albo dodaj dokument.</p>':'';
  const inputs=c.fields.filter(f=>!f.referenceOnly&&!['reference','payer'].includes(f.scope));const found=new Set(inputs.filter(f=>f.use).map(f=>f.field));const missing=[...(!['eventDate','dueDate','childBirthDate','sickness.start','care.start'].some(f=>found.has(f))?['Data zdarzenia / świadczenia']:[]),...(focus==='family'&&!found.has('count')?['Liczba dzieci']:[]),...(!found.has('coverage')?['Ubezpieczenie chorobowe']:[]),...(!['basis','salary','wage.gross'].some(f=>found.has(f))?['Podstawa wymiaru lub wynagrodzenia']:[])];if(missing.length)node.innerHTML+='<p class="doc-empty"><strong>Brak potwierdzonych informacji z tego odczytu:</strong> '+missing.map(esc).join(', ')+'. Zaznacz właściwe pola lub uzupełnij je ręcznie. Pozostawione wartości bieżącego formularza również wymagają sprawdzenia przed obliczeniem.</p>';if(!inputs.length)node.innerHTML+='<p class="doc-empty">Brak danych do użycia. Dodaj PDF lub brakujące pola ręcznie. Nierozpoznany układ wymaga sprawdzenia w podglądzie.</p>';
  const candidates=dialog.querySelector('#doc-candidates');if(candidates){const values=c.documents.flatMap(d=>d.pages.flatMap(p=>p.analysis.unmapped.filter(x=>x.value).map(v=>({...v,documentId:d.id,filename:d.file.name}))));candidates.innerHTML=values.length?values.map((v,i)=>`<article class="doc-candidate"><strong>${esc(v.value)}</strong><span>${esc(v.evidence)}</span><small>${esc(v.filename)} · strona ${v.page}</small><button class="text-button" data-assign-candidate="${i}">Zobacz i przypisz do pola</button></article>`).join(''):'<p>Brak dodatkowych wartości do przypisania.</p>';candidates.querySelectorAll('[data-assign-candidate]').forEach(b=>b.onclick=()=>{pendingSource=values[Number(b.dataset.assignCandidate)];showSource(pendingSource.documentId,pendingSource.page,pendingSource.bbox);dialog.querySelector('.doc-manual').open=true;dialog.querySelector('#doc-manual-value').value=pendingSource.value;dialog.querySelector('#doc-manual-field').focus();});}for(const f of inputs){const identity=f.field.startsWith('identity.')||f.field==='child.name',information=f.scope==='information';const d=c.documents.find(d=>d.id===f.documentId);const card=document.createElement('article');card.className='doc-field '+(conflictIds.has(f.id)?'doc-conflict':'');card.innerHTML=`<div class="doc-field-title"><label><input type="checkbox" data-use ${f.use?'checked':''} ${identity||information?'disabled':''}> <strong>${esc(f.label)}</strong></label><small>${identity?'Tylko do rozróżnienia osób — nie zapisujemy w kalkulatorze':information?'Informacja pomocnicza':f.method==='manual'?'Uzupełniono ręcznie':f.confirmed?'Potwierdzono przez użytkownika':f.needsReview?'Odczytano — wymaga sprawdzenia':'Odczytano z dokumentu — sprawdź'}</small></div><div class="doc-field-edit"><label>Wartość${valueControl(f)}</label>${f.scope==='person'?`<label>Właściciel<select data-owner><option value="">Przypisz osobę</option><option value="0" ${String(f.assignment)==='0'?'selected':''}>Matka / opiekun 1</option><option value="1" ${String(f.assignment)==='1'?'selected':''}>Ojciec / opiekun 2</option></select></label><label>Tytuł<select data-title>${[0,1,2,3].map(i=>`<option value="${i}" ${Number(f.title||0)===i?'selected':''}>${i?'Dodatkowy '+(i+1):'Główny'}</option>`).join('')}</select></label>`:''}${f.scope==='child'?`<label>Dziecko<input data-child type="number" min="1" max="12" value="${Number(f.child||0)+1}"></label>`:''}${f.field.startsWith('wage.')?`<label>Miesiąc<input data-period type="month" value="${esc(f.period||'')}"></label>`:''}</div><div class="doc-source"><span>${esc(d?.file.name||'Wpis ręczny')}${f.page?' · strona '+f.page:''} · ${esc(f.method)}</span>${f.documentId?'<button class="text-button" data-source>Zobacz źródło</button>':''}</div>${conflictIds.has(f.id)?'<p>Różne wartości — sprawdź źródła i pozostaw zaznaczoną właściwą.</p>':''}`;
   card.dataset.documentField=f.field;card.dataset.documentScope=f.scope;
   card.querySelector('[data-use]').onchange=e=>{f.use=e.target.checked;drawFields();};const control=card.querySelector('[data-value]');control.onchange=()=>{const check=documentValue(f.valueType,control.value);if(!check.valid){control.setCustomValidity(check.reason);control.reportValidity();f.use=false;return;}control.setCustomValidity('');f.value=check.value;f.confirmed=false;f.needsReview=true;drawFields();};card.querySelector('[data-owner]')?.addEventListener('change',e=>{f.assignment=e.target.value;drawFields();});card.querySelector('[data-title]')?.addEventListener('change',e=>{f.title=Number(e.target.value);drawFields();});card.querySelector('[data-child]')?.addEventListener('change',e=>f.child=Number(e.target.value)-1);card.querySelector('[data-period]')?.addEventListener('change',e=>f.period=e.target.value);card.querySelector('[data-source]')?.addEventListener('click',()=>showSource(f.documentId,f.page,f.bbox));node.append(card);}
 }
 function valueControl(f){const options=f.valueType==='occupation'?[['employee','Pracownik'],['contract','Zlecenie'],['business','Działalność'],['startup','Ulga na start'],['uninsured','Bez ubezpieczenia'],['krus','KRUS']]:f.valueType==='coverage'?[['unknown','Nieustalone'],['compulsory','Obowiązkowe'],['voluntary','Dobrowolne'],['none','Potwierdzony brak']]:['certificate','boolean'].includes(f.valueType)?[['yes','Tak'],['unknown','Nieustalone'],['no','Nie']]:null;return options?`<select data-value>${options.map(([v,l])=>`<option value="${v}" ${f.value===v?'selected':''}>${l}</option>`).join('')}</select>`:`<input data-value type="${f.valueType==='date'?'date':['money','integer','fte'].includes(f.valueType)?'number':'text'}" ${f.valueType==='money'||f.valueType==='fte'?'step="0.01"':''} value="${esc(String(f.value))}">`;}
 async function showSource(id,page,bbox){const doc=session.current().documents.find(d=>d.id===id);if(!doc)return;preview={id,page,bbox};const serial=++previewSerial,canvas=dialog.querySelector('#doc-canvas'),controls=dialog.querySelector('#doc-preview-controls'),message=dialog.querySelector('#doc-preview-message');controls.innerHTML=`<strong>${esc(doc.file.name)}</strong><div class="doc-page-controls"><button class="secondary" id="doc-page-prev" ${page<=1?'disabled':''}>‹</button><label>Strona <input id="doc-page-number" type="number" min="1" max="${doc.pageCount||1}" value="${page}"> z ${doc.pageCount||'—'}</label><button class="secondary" id="doc-page-next" ${page>=(doc.pageCount||1)?'disabled':''}>›</button></div>`;const go=n=>showSource(id,Math.max(1,Math.min(doc.pageCount||1,n)));controls.querySelector('#doc-page-prev').onclick=()=>go(page-1);controls.querySelector('#doc-page-next').onclick=()=>go(page+1);controls.querySelector('#doc-page-number').onchange=e=>go(Number(e.target.value)||1);message.textContent='Przygotowujemy stronę…';try{await (previewJob=previewJob.catch(()=>{}).then(()=>serial===previewSerial?session.render(id,page,canvas,bbox):undefined));if(serial!==previewSerial)return;canvas.hidden=false;message.textContent=bbox?'Wyróżniony obszar zawiera odczytaną wartość. Sprawdź również otaczający tekst.':'Skrypty, podpisy i aktywne elementy PDF nie są wykonywane ani weryfikowane.';}catch{message.textContent='Nie udało się wyświetlić strony. Dla chronionego PDF użyj hasła i odczytaj dokument ponownie.';}}
 async function examples(){stage='review';draw();const drop=dialog.querySelector('#doc-drop');const panel=document.createElement('section');panel.className='doc-samples';panel.innerHTML='<h2>Własne przykłady fikcyjne</h2><p>To syntetyczne zestawy aplikacji, nie dokumenty konkursowe ani oficjalne formularze.</p><button class="secondary" data-sample="employee">Matka — wniosek i potwierdzona podstawa</button><button class="secondary" data-sample="uninsured">Potwierdzony brak chorobowego</button><button class="secondary" data-sample="scan">Skan poświadczenia ubezpieczenia</button>';drop.before(panel);panel.querySelectorAll('[data-sample]').forEach(button=>button.onclick=async()=>{try{session.newCase();const names=button.dataset.sample==='employee'?['wniosek','podstawa','ubezpieczenie','decyzja']:button.dataset.sample==='uninsured'?['wniosek','brak-ubezpieczenia']:['skan'];const files=[];for(const name of names){const response=await fetch(new URL('./examples/documents/'+name+'.pdf',import.meta.url));if(!response.ok)throw new Error('Nie udało się wczytać przykładu.');files.push(new File([await response.blob()],name+'-fikcyjny.pdf',{type:'application/pdf'}));}await add(files);panel.remove();}catch(e){error(e);}});}
 function drawReference(){const node=dialog.querySelector('#doc-reference-fields'),reference=session.current().fields.filter(f=>f.referenceOnly);if(!node)return;node.innerHTML=reference.map(f=>`<p><strong>${esc(f.label)}</strong>: ${esc(String(f.value))} · strona ${f.page}<button class="text-button" data-ref-source="${f.id}">Zobacz źródło</button></p>`).join('')+`<label>Osoba<select id="doc-ref-parent"><option value="0">Matka / opiekun 1</option><option value="1">Ojciec / opiekun 2</option></select></label><label>Początek okresu<input id="doc-ref-start" type="date"></label><label>Koniec okresu<input id="doc-ref-end" type="date"></label><label>Kwota referencyjna brutto (potwierdź w decyzji)<input id="doc-ref-gross" type="number" step="0.01" value="${reference.find(f=>f.field==='reference.gross')?.value??''}"></label><label class="doc-confirm"><input id="doc-ref-comparable" type="checkbox"> Ta sama osoba, rodzaj świadczenia i okres; obie kwoty są brutto.</label><button class="secondary" id="doc-ref-run">Porównaj z niezależnym wynikiem kalkulatora</button><div id="doc-ref-result"></div>`;node.querySelectorAll('[data-ref-source]').forEach(b=>b.onclick=()=>{const f=reference.find(f=>f.id===b.dataset.refSource);showSource(f.documentId,f.page,f.bbox);});node.querySelector('#doc-ref-run').onclick=()=>{const r=compareDocumentReference(getResult(),reference,{parent:node.querySelector('#doc-ref-parent').value,start:node.querySelector('#doc-ref-start').value,end:node.querySelector('#doc-ref-end').value,gross:node.querySelector('#doc-ref-gross').value===''?null:Number(node.querySelector('#doc-ref-gross').value),comparable:node.querySelector('#doc-ref-comparable').checked,status:reference.find(f=>f.field==='reference.status')?.value});node.querySelector('#doc-ref-result').textContent=[r.message,r.actual!=null?'Wynik kalkulatora: '+r.actual.toFixed(2)+' zł':'',r.expected!=null?'Wynik referencyjny: '+r.expected.toFixed(2)+' zł':'',r.difference!=null?'Różnica: '+r.difference.toFixed(2)+' zł':'',r.rulesVersion?'Wersja reguł: '+r.rulesVersion:'',r.assessment?'Ocena: '+r.assessment:''].filter(Boolean).join('\n');};}
 return {open:()=>{draw();if(!dialog.open)dialog.showModal();},session,close:()=>dialog.close()};
}
